370:fn benchmark_async_payload_encode(criterion: &mut Criterion) {
371:    let cases = payload_cases();
372:    verify_cpu_paths(&cases);
373:
374:    let mut group = criterion.benchmark_group("prost_async_payload_encode");
375:    for case in &cases {
376:        let encoded_len = case.message.encoded_len();
377:        let payloads = payload_count(&case.message);
378:        let requests_per_iter = requests_per_iteration(encoded_len);
379:
380:        group.bench_function(
381:            format!(
382:                "{} / CPU Prost Message::encode / requests={} bytes_per_request={} bytes_per_iter={} payloads_per_request={}",
383:                case.name,
384:                requests_per_iter,
385:                encoded_len,
386:                requests_per_iter * encoded_len,
387:                payloads
388:            ),
389:            |b| {
390:                let corpus = payload_corpus(&case.message);
391:                let mut outputs = output_corpus(corpus.len(), encoded_len);
392:                let mut request_index = 0;
393:                b.iter(|| {
394:                    let mut encoded_bytes = 0;
395:                    for _ in 0..requests_per_iter {
396:                        let index = next_payload_index(&corpus, &mut request_index);
397:                        let output = &mut outputs[index];
398:                        output.clear();
399:                        corpus[index]
400:                            .encode(output)
401:                            .expect("CPU Prost encode succeeds");
402:                        encoded_bytes += output.len();
403:                    }
404:                    black_box(encoded_bytes);
405:                });
406:            },
407:        );
408:
409:        group.bench_function(
410:            format!(
411:                "{} / async CPU Prost encode_async_ref / requests={} bytes_per_request={} bytes_per_iter={} payloads_per_request={}",
412:                case.name,
413:                requests_per_iter,
414:                encoded_len,
415:                requests_per_iter * encoded_len,
416:                payloads
417:            ),
418:            |b| {
419:                let corpus = payload_corpus(&case.message);
420:                let mut outputs = output_corpus(corpus.len(), encoded_len);
421:                let mut request_index = 0;
422:                b.iter(|| {
423:                    let mut encoded_bytes = 0;
424:                    for _ in 0..requests_per_iter {
425:                        let index = next_payload_index(&corpus, &mut request_index);
426:                        let output = &mut outputs[index];
427:                        output.clear();
428:                        let mut target = BufMutEncodeTarget::new(output);
429:                        poll_until_ready(corpus[index].encode_async_ref(&mut target))
430:                            .expect("async CPU Prost encode succeeds");
431:                        encoded_bytes += output.len();
432:                    }
433:                    black_box(encoded_bytes);
434:                });
435:            },
436:        );
437:    }
438:    group.finish();
439:
440:    benchmark_cpu_thread_matrix(criterion, &cases);
441:
442:    benchmark_dsa_paths(criterion, &cases);
443:}
